return ['domain'=>'zinn-cache-pro','plural-forms'=>'nplurals=1; plural=0;','language'=>'tg','project-id-version'=>'zinn-cache-pro','pot-creation-date'=>'2026-09-02T07:33:51+00:00','po-revision-date'=>'2026-09-02T07:33:51+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache Engine'=>'Zinn® Cache Engine','https://zinndigital.com/wordpress-plugins/zinn-cache-pro'=>'https://zinndigital.com/wordpress-plugins/zinn-cache-pro','A complete caching and optimisation engine for WordPress: full-page cache, object cache, database cleanup and CSS/JS optimisation. Install this when your host does not provide a cache layer of its own — on Zinn Digital® hosting install Zinn® Cache instead. Full-page caching requires a LiteSpeed or OpenLiteSpeed server with the LSCache module. A GPLv3 fork of the LiteSpeed Cache plugin.'=>'Як муҳаррики пурраи ҳифзи ниҳон (кеш) ва беҳсозӣ барои WordPress: кеши саҳифаи пурра, кеши объектӣ, тозакунии пойгоҳи додаҳо ва беҳсозии CSS/JS. Инро вақте насб кунед, ки мизбони шумо қабати кеши худро надорад — дар мизбонии Zinn Digital® ба ҷои он Zinn® Cache-ро насб кунед. Кеш кардани саҳифаи пурра ба сервери LiteSpeed ё OpenLiteSpeed бо модули LSCache ниёз дорад. Як шохаи (fork) GPLv3-и плагини LiteSpeed Cache.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','%d hours'=>'%d соат','%d hour'=>'%d соат','%d minutes'=>'%d дақиқа','%d minute'=>'%d дақиқа','Purged All!'=>'Ҳамааш тоза карда шуд!','Purged the blog!'=>'Блог тоза карда шуд!','Purged the URL!'=>'URL тоза карда шуд!','Purged!'=>'Тоза карда шуд!','Failed to upgrade.'=>'Навсозӣ муваффақ нашуд.','Upgraded successfully.'=>'Бомуваффақият навсозӣ шуд.','Dashboard'=>'Пештахта','Presets'=>'Танзимоти пешфарз','General'=>'Умумӣ','Cache'=>'Кэш','CDN'=>'CDN','Image Optimization'=>'Оptimizatsiyai tasvirҳо','Page Optimization'=>'Оптимизатсияи саҳифа','Database'=>'Пойгоҳи додаҳо','Crawler'=>'Хазанда','Toolbox'=>'Афзорҳо','Cookie Name'=>'Номи куки','Cookie Values'=>'Арзишҳои кукиҳо','Remove cookie simulation'=>'Тоза кардани симулятсияи кукиҳо','Add new cookie to simulate'=>'Илова кардани кукии нав барои эмуляция','CDN URL to be used. For example, %s'=>'URL-и CDN барои истифода. Масалан, %s','Remove CDN URL'=>'Нест кардани URL-и CDN','Add new CDN URL'=>'Илова кардани URL-и нави CDN','ON'=>'ФАЪОЛ','OFF'=>'ХОМУШ','Settings'=>'Танзимот','Dismiss'=>'Рад кардан','Save Changes'=>'Тағйиротро захира кунед','This value is overwritten by the %s variable.'=>'Ин қимат бо тағйирёбандаи %s иваз карда мешавад.','This value is overwritten by the filter.'=>'Ин қимат аз ҷониби филтр иваз карда мешавад.','This value is overwritten by the PHP constant %s.'=>'Ин қимат бо доимиёти PHP %s иваз карда мешавад.','This value is overwritten by the primary site setting.'=>'Ин қимат аз ҷониби танзимоти асосии сайт аз нав сабт мешавад.','This value is overwritten by the Network setting.'=>'Ин маблағ аз ҷониби танзимоти Шабака бознавишта мешавад.','Currently set to %s'=>'Дар ай ҳол ба %s гузошта шудааст','Value from filter applied'=>'Qiymati аз филтри татбиқшуда','seconds'=>'сонияҳо','Default value'=>'Qiмəти пешфарз','Invalid rewrite rule'=>'Қоидаи бознависии нодуруст','Path must end with %s'=>'Масир бояд бо %s анҷом ёбад','Minimum value'=>'Арзиши ҳадди ақал','Maximum value'=>'Қимати максималӣ','Zero, or'=>'Сифр, ё','Larger than'=>'Аз калонтар','Smaller than'=>'Хурдтар аз','Value range'=>'Доираи қиматҳо','Invalid IP'=>'IP-и нодуруст','API'=>'API','Server variable(s) %s available to override this setting.'=>'Тағйирёбанда(ҳо)-и сервер %s барои бекор кардани ин танзимот дастрас аст.','The URLs will be compared to the REQUEST_URI server variable.'=>'URL-ҳо бо тағйирёбандаи сервери REQUEST_URI муқоиса карда мешаванд.','For example, for %1$s, %2$s can be used here.'=>'Масалан, барои %1$s, %2$s-ро дар ин ҷо истифода бурдан мумкин аст.','To match the beginning, add %s to the beginning of the item.'=>'Барои мувофиқат кардан ба ибтидо, %s-ро ба ибтидои элемент илова кунед.','To do an exact match, add %s to the end of the URL.'=>'Барои дарёфти мувофиқати дақиқ, %s-ро ба охири URL илова кунед.','One per line.'=>'Дар як сатр.','%s groups'=>'%s гурӯҳҳо','%s images'=>'%s тасвирҳо','%s group'=>'гурӯҳи %s','%s image'=>'Тасвири %s','No fields'=>'Ягон майдон нест','The user with id %s has editor access, which is not allowed for the role simulator.'=>'Корбари дорои рақами мушаххаси %s дастрасии муҳаррир дорад, ки барои симулятори нақш иҷозат дода намешавад.','Options saved.'=>'Интихобҳо захира шуданд.','Notified Cloudflare to set development mode to %s successfully.'=>'Ба Cloudflare бомуваффақият хабар дода шуд, ки ҳолати таҳияро ба %s гузорад.','Cloudflare API is set to off.'=>'API-и Cloudflare ба ҳолати хомӯш гузошта шудааст.','Notified Cloudflare to purge all successfully.'=>'Cloudflare бомуваффақият огоҳонида шуд, ки ҳамаашро тоза кунад.','No available Cloudflare zone'=>'Ягон минтақаи дастраси Cloudflare нест','Failed to communicate with Cloudflare'=>'Тамос бо Cloudflare муяссар нашуд','Communicated with Cloudflare successfully.'=>'Бо Cloudflare бомуваффақият муошират карда шуд.','Failed to validate %s activation data.'=>'Санҷиши маъмориҳои фаъолсозии %s муваффақ нашуд.','Failed to parse %s activation status.'=>'Тартиби фаъолсозии %s таҳлил карда нашуд.','%s activation data expired.'=>'Маълумоти фаъолсозии %s мӯҳлаташ гузашт.','Congratulations, %s successfully set this domain up for the anonymous online services.'=>'Табрик мекунем, %s ин доменихро бомуваффақият барои хидматрасониҳои беноми онлайни насб кард.','Congratulations, %s successfully set this domain up for the online services.'=>'Табрик мекунем, %s ин доменро бомуваффақият барои хидматҳои онлайн танзим кард.','Congratulations, %s successfully set this domain up for the online services with CDN service.'=>'Муборакбод, %s ин доменро бомуваффақият барои хидматҳои онлайнӣ бо хидмати CDN танзим кард.','Site not recognized. QUIC.cloud deactivated automatically. Please reactivate your QUIC.cloud account.'=>'Сомона шинохта нашуд. QUIC.cloud ба таври худкор ғайрифаъол карда шуд. Лутфан ҳисоби QUIC.cloud-и худро аз нав фаъол созед.','Click here to proceed.'=>'Барои идома ин ҷоро клик кунед.','QUIC.cloud\'s access to your WP REST API seems to be blocked.'=>'Дастрасии QUIC.cloud ба WP REST API-и шумо баста шудааст ба назар мерасад.','Failed to get echo data from WPAPI'=>'Гирифтани маълумоти эхо аз WPAPI муяссар нашуд','You need to set the %1$s first. Please use the command %2$s to set.'=>'Шумо аввал бояд %1$s-ро танзим кунед. Лутфан барои танзим фармони %2$s-ро истифода баред.','Server IP'=>'IP-и сервер','You need to activate QC first.'=>'Шумо бояд аввал QC-ро фаъол созед.','Cert or key file does not exist.'=>'Файли шаҳодатнома ё калид вуҷуд надорад.','Reset %s activation successfully.'=>'Фаъолсозии %s бомуваффақият барқарор карда шуд.','Linked to QUIC.cloud preview environment, for testing purpose only.'=>'Ба муҳити пешнамоиши QUIC.cloud пайваст шудааст, танҳо барои мақсадҳои озмоишӣ.','Cloud Error'=>'Хатогии абр','No available Cloud Node after checked server load.'=>'Пас аз санҷиши сарбориҳои сервер Ҳеҷ Ноҳи Дигари Абрӣ (Cloud Node) дастрас нест.','No available Cloud Node.'=>'Ягон Гурҳи абрӣ дастрас нест.','In order to use QC services, need a real domain name, cannot use an IP.'=>'Барои истифодаи хидматҳои QC домени воқеӣ лозим аст, суроғаи IP-ро истифода бурдан мумкин нест.','Please try after %1$s for service %2$s.'=>'Лутфан пас аз %1$s барои хизматрасонии %2$s кӯшиш кунед.','Failed to request via WordPress'=>'Иҷрои дархост тавассути WordPress ноком шуд','Cloud server refused the current request due to unpulled images. Please pull the images first.'=>'Сервери абрӣ дархости ҷориро бинобар тасвирҳои накашидашуда рад кард. Лутфан аввал тасвирҳоро кашед.','Your domain_key has been temporarily blocklisted to prevent abuse. You may contact support at QUIC.cloud to learn more.'=>'Домени domain_key-и шумо барои пешгирӣ аз истифодаи сӯиқасдона вақтинча ба рӯйхати сиёҳ дохил карда шуд. Барои маълумоти бештар шумо метавонед бо хадамоти дастгирии QUIC.cloud тамос гиред.','Cloud server refused the current request due to rate limiting. Please try again later.'=>'Сервери абрӣ дархости мазкурро бо сабаби маҳдуд кардани суръат рад кард. Лутфан, баъдтар бори дигар кӯшиш кунед.','Redetected node'=>'Гиреҳи дубора ошкоршуда','We are working hard to improve your online service experience. The service will be unavailable while we work. We apologize for any inconvenience.'=>'Мо барои беҳтар кардани таҷрибаи хидматрасонии онлайни шумо сахт мекӯшем. Ҳангоми корҳои анҷомдодаистода хидмат дастнорас хоҳад буд. Барои ноқулайлиҳои пешомада узр мепурсем.','Message from QUIC.cloud server'=>'Паём аз сервери QUIC.cloud','Good news from QUIC.cloud server'=>'Хбари хуш аз сервери QUIC.cloud','%1$s plugin version %2$s required for this action.'=>'Барои ин амалиёт версияи плагини %1$s %2$s лозим аст.','Failed to communicate with QUIC.cloud server'=>'Бarqaрор кардани алоқа бо сервери QUIC.cloud муяссар нашуд','Sync QUIC.cloud status successfully.'=>'Ҳолати QUIC.cloud бомуваффақият ҳамоҳанг карда шуд.','Sync credit allowance with Cloud Server successfully.'=>'Маблағи лимитӣ бо Cloud Server бомуваффақият ҳамоҳанг карда шуд.','Saving option failed. IPv4 only for %s.'=>'Зерҳанигардонии имконот номуваффақ шуд. Танҳо IPv4 барои %s.','Changed setting successfully.'=>'Танзимот бомуваффақият иваз карда шуд.','Notified LiteSpeed Web Server to purge everything.'=>'Барои тоза кардани ҳама чиз ба LiteSpeed Web Server огоҳинома фиристода шуд.','Notified LiteSpeed Web Server to purge the list.'=>'Барои тоза кардани рӯйхат ба LiteSpeed Web Server хабар дода шуд.','Sitemap cleaned successfully'=>'Харитаи сайт бо муваффақият тоза карда шуд','No valid sitemap parsed for crawler.'=>'Барои хазанда ягон сайти маҳаллисозии эътиборнок таҳлил нашудааст.','Sitemap created successfully: %d items'=>'Харитаи сайт бо муваффақият сохта шуд: %d элементҳо','Crawler disabled list is cleared! All crawlers are set to active! '=>'Рӯйхати ботҳои ҷустуҷӯии ғайрифаъолшуда пок карда шуд! Ҳамаи ботҳои ҷустуҷӯӣ ба ҳолати фаъол гузаронида шуданд!','Started async crawling'=>'Хғизонии асинхронӣ оғоз шуд','Guest'=>'Меҳмон','Manually added to blocklist'=>'Ба таври дастӣ ба рӯйхати сиёҳ илова карда шудааст','Previously existed in blocklist'=>'Пештар дар рӯйхати сиёҳ вуҷуд дошт','The database has been upgrading in the background since %s. This message will disappear once upgrade is complete.'=>'Пойгоҳи додаҳо аз %s инҷониб дар замина навсозӣ шуда истодааст. Ин паём пас аз ба охир расидани навсозӣ нест мешавад.','Clean all successfully.'=>'Ҳама бомуваффақият тоза карда шуданд.','Clean post revisions successfully.'=>'Ивазкуниҳои навиштаҳо бомуваффақият тоза карда шуданд.','Clean orphaned post meta successfully.'=>'Метаи паёмҳои бесоҳиб бо муваффақият тоза карда шуд.','Clean auto drafts successfully.'=>'Лоиҳаҳои худкори хомӯш бомуваффақият тоза карда шуданд.','Clean trashed posts and pages successfully.'=>'Навиштаҳо ва саҳифаҳои ба сабати ахлот партофташуда бомуваффақият тоза карда шуданд.','Clean spam comments successfully.'=>'Шарҳҳои спам бо муваффақият тоза карда шуданд.','Clean trashed comments successfully.'=>'Шарҳҳои ба сабад партофташуда бомуваффақият тоза карда шуданд.','Clean trackbacks and pingbacks successfully.'=>'Пайгириҳо ва оғози пайвандҳоро бомуваффақият тоза кунед.','Clean expired transients successfully.'=>'Гузарандаҳои муҳлати онҳо гузашта бо муваффақият тоза карда шуданд.','Clean all transients successfully.'=>'Ҳамаи гузаришҳо бомуваффақият тоза карда шуданд.','Optimized all tables.'=>'Ҳамаи ҷадвалҳо мутобиқ карда шуданд.','Converted to InnoDB successfully.'=>'Ба InnoDB бо муваффақият гузаронида шуд.','Invalid log type.'=>'Намуди сабти нодуруст.','Log file not found.'=>'Файли гузориш ёфт нашуд.','This setting is %1$s for certain qualifying requests due to %2$s!'=>'Ин танзимот барои баъзе дархостҳои мувофиқ аз сабаби %2$s %1$s аст!','This setting will regenerate crawler list and clear the disabled list!'=>'Ин танзимот рӯйхати хазандаҳоро аз нав эҷод мекунад ва рӯйхати ғайрифаъолшударо тоза мекунад!','This site utilizes caching in order to facilitate a faster response time and better user experience. Caching potentially stores a duplicate copy of every web page that is on display on this site. All cache files are temporary, and are never accessed by any third party, except as necessary to obtain technical support from the cache plugin vendor. Cache files expire on a schedule set by the site administrator, but may easily be purged by the admin before their natural expiration, if necessary. We may use QUIC.cloud services to process & cache your data temporarily.'=>'Ин сайти мазкур ҷиҳати таъмини вақти посухдиҳии тезтар ва таҷрибаи беҳтари корбар аз захираи муваққатӣ (кеш) истифода мебарад. Захираи муваққатӣ эҳтимолан нусхаи дуюми ҳар як саҳифаи вебро, ки дар ин сайт намоиш дода мешавад, маҳфуз медорад. Ҳамаи файлҳои захираи муваққатӣ муваққатӣ мебошанд ва ҳеҷ гоҳ аз ҷониби ягон тарафи сеюм дастнорас нестанд, ба истиснои ҳолатҳои зарурии гирифтани дастгирии техникӣ аз фурӯшандаи плагини кеш. Файлҳои захираи муваққатӣ дар асоси ҷадвали муқаррарнамудаи мудири сайт мӯҳлати корашон ба охир мерасад, аммо дар ҳолати зарурӣ метавонанд пеш аз мӯҳлати табиии худ ба осонӣ аз ҷониби мудир тоза карда шаванд. Мо метавонем аз хадамоти QUIC.cloud барои коркард ва захираи муваққатии маълумоти шумо истифода барем.','Please see %s for more details.'=>'Барои тафсилоти бештар лутфан ба %s муроҷиат кунед.','Learn More'=>'Маълумоти бештар','Both full and partial strings can be used.'=>'Ҳам сатрҳои пурра ва ҳам қисман истифода шуда метавонанд.','Both full URLs and partial strings can be used.'=>'Ҳам суроғаҳои пурраи URL ва ҳам сатрҳои қисман истифода шуда метавонанд.','This setting will edit the .htaccess file.'=>'Ин танзимот файли .htaccess-ро таҳрир мекунад.','The queue is processed asynchronously. It may take time.'=>'Навбат ба таври асинхронӣ коркард мешавад. Ин метавонад вақт гирад.','You will need to finish %s setup to use the online services.'=>'Барои истифода бурдани хидматҳои онлайн ба шумо лозим меояд, ки насбкунии %s-ро ба охир расонед.','Click here to set.'=>'Барои танзим инҷо клик кунед.','You have used all of your daily quota for today.'=>'Шумо тамоми квотаи рӯзонаи худро барои имрӯз истифода бурдаед.','Learn more or purchase additional quota.'=>'Маълумоти бештар гиред ё квотаи иловагӣ харидорӣ кунед.','You have used all of your quota left for current service this month.'=>'Шумо тамоми квотаи боқимондаи худро барои хизматрасонии ҷорӣ дар ин моҳ истифода бурдаед.','You have too many requested images, please try again in a few minutes.'=>'Шумо тасвирҳои дархостшудаи зиёде доред, лутфан чанд дақиқа пас дубора кӯшиш кунед.','You have images waiting to be pulled. Please wait for the automatic pull to complete, or pull them down manually now.'=>'Шумо тасвирҳое доред, ки интизори гирифтан мебошанд. Лутфан интизор шавед, ки гирифтани худкор ба охир расад, ё онҳоро ҳозир дастӣ гиред.','The image list is empty.'=>'Рӯйхати тасвирҳо холӣ аст.','Not enough parameters. Please check if the QUIC.cloud connection is set correctly'=>'Параметрҳо кофӣ нестанд. Лутфан санҷед, ки оё пайсти QUIC.cloud дуруст танзим шудааст ё не','There is proceeding queue not pulled yet.'=>'Навбати иҷрокунанда ҳанӯз гирифта нашудааст.','There is proceeding queue not pulled yet. Queue info: %s.'=>'Дар навбати иҷро то ҳол навбате кашида нашудааст. Маълумоти навбат: %s.','The site is not a valid alias on QUIC.cloud.'=>'Дар QUIC.cloud сайт тахаллуси эътиборнок нест.','The site is not registered on QUIC.cloud.'=>'Сомона дар QUIC.cloud сабти ном нашудааст.','The QUIC.cloud connection is not correct. Please try to sync your QUIC.cloud connection again.'=>'Пайсти QUIC.cloud нодуруст аст. Лутфан кӯшиш кунед, ки пайсти QUIC.cloud-и худро аз нав ҳамоҳангсозӣ кунед.','The current server is under heavy load.'=>'Сервери ҷорӣ зери сарбории вазнин қарор дорад.','Online node needs to be redetected.'=>'Гиреҳи онлайн бояд дубора муайян карда шавад.','Credits are not enough to proceed the current request.'=>'Барои идома додани дархости мазкур кредитҳо кофӣ нестанд.','%s file not writable.'=>'Файли %s барои навиштан дастнорас аст.','Could not find %1$s in %2$s.'=>'%2$s да %1$s ёфт нашуд.','Invalid login cookie. Please check the %s file.'=>'Кукии вуруди нодуруст. Лутфан файли %s-ро тафтиш кунед.','Failed to back up %s file, aborted changes.'=>'Нусхабардории эҳтиётии файли %s бозмонд, тағйирот бекор карда шуданд.','%s file not readable.'=>'%s файл хонда намешавад.','Failed to get %s file contents.'=>'Гирифтани мундариҷаи файли %s муяссар нашуд.','Failed to create table %1$s! SQL: %2$s.'=>'Эҷоди ҷадвали %1$s муваффақ нашуд! SQL: %2$s.','Crawler disabled by the server admin.'=>'Коркардкунанда аз ҷониби админи сервер ғайрифаъол карда шудааст.','Previous request too recent. Please try again later.'=>'Дархости пешин хеле барвақт аст. Лутфан, баъдтар бори дигар кӯшиш кунед.','Previous request too recent. Please try again after %s.'=>'Дархости пешин хеле нав аст. Лутфан пас аз %s дубора кӯшиш кунед.','Your application is waiting for approval.'=>'Аризаи шумо дар интизори тасдиқ аст.','The callback validation to your domain failed due to hash mismatch.'=>'Санҷиши бозхост ба домении шумо аз сабаби номувофиқатии ҳеш (hash) номвафқ шуд.','The callback validation to your domain failed. Please make sure there is no firewall blocking our servers.'=>'Санҷиши посух ба домени шумо ноком шуд. Лутфан боварӣ ҳосил кунед, ки ягон брандмауэр (девори оташ) серверҳои моро маҳдуд намекунад.','The callback validation to your domain failed. Please make sure there is no firewall blocking our servers. Response code: '=>'Санҷиши бозхост ба домении шумо ноком шуд. Лутфан боварӣ ҳосил кунед, ки ягон девори оташин (файрвол) серверҳои моро масдуқ намекунад. Рамзи ҷавоб:','Your domain has been forbidden from using our services due to a previous policy violation.'=>'Домени шумо ба сабаби вайрон кардани сиёсати пешин аз истифодаи хидматҳои мо маҳрум карда шудааст.','You cannot remove this DNS zone, because it is still in use. Please update the domain\'s nameservers, then try to delete this zone again, otherwise your site will become inaccessible.'=>'Шумо наметавонед ин минтақаи DNS-ро нест кунед, зеро он ҳанӯз истифода мешавад. Лутфан, номгузорҳои доменро навсозӣ кунед ва сипас кӯшиш кунед, ки ин минтақаро дубора нест кунед, вагарна сайти шумо дастнорас мешавад.','Unknown error'=>'Хатогии номаълум','Filename is empty!'=>'Номи файл холӣ аст!','Folder does not exist: %s'=>'Папка вуҷуд надорад: %s','Can not create folder: %1$s. Error: %2$s'=>'Эҷод кардани ҷузвдон ғайриимкон аст: %1$s. Хатогӣ: %2$s','Folder is not writable: %s.'=>'Ҷузвдон қобили навиштан нест: %s.','File %s is not writable.'=>'Файли %s барои навиштан дастнорас аст.','Failed to write to %s.'=>'Навиштан ба %s муяссар нашуд.','Guest Mode lists synced successfully.'=>'Рӯйхатҳои Ҳолати меҳмон бомуваффақият ҳамоҳанг карда шуданд.','Failed to sync Guest Mode lists.'=>'Ҳамоҳангсозии рӯйхатҳои Ҳолати меҳмон муяссар нашуд.','%1$s %2$s files left in queue'=>'%1$s %2$s файл дар навбат мондааст','Cancel'=>'Бекор кардан','Purge this page'=>'Тоза кардани ин саҳифа','Mark this page as '=>'Ин саҳифаро ҳамчун гузоштан ба нишон','Forced cacheable'=>'Маҷбурӣ каш-шаванда','Non cacheable'=>'Кэшнашаванда','Private cache'=>'Кэши хусусӣ','No optimization'=>'Беҳинасозӣ нест','More settings'=>'Танзимоти бештар','Purge All'=>'Тозакунии ҳамагӣ','LSCache'=>'LSCache','CSS/JS Cache'=>'Кэши CSS/JS','Cloudflare'=>'Cloudflare','Object Cache'=>'Кэши объектҳо','Opcode Cache'=>'Кэши амалиётҳо','Localized Resources'=>'Захираҳои маҳаллисозишуда','LQIP Cache'=>'Кэши LQIP','Gravatar Cache'=>'Кэши Граватар','Enable All Features'=>'Фаъол кардани ҳамаи хусусиятҳо','Zinn® Cache Engine Purge All'=>'Тозакунии пурраи муҳаррики кэши Zinn®','Manage'=>'Идоракунӣ','Remove all previous unfinished image optimization requests.'=>'Ҳама дархостҳои қаблии оптимизатсияи тасвирҳои анҷомнашударо нест кунед.','Clean Up Unfinished Data'=>'Тоза кардани маълумоти нотамом','Install %s'=>'Насби %s','Install Now'=>'Ҳоло насб кунед','<a href="%1$s" %2$s>View version %3$s details</a> or <a href="%4$s" %5$s target="_blank">update now</a>.'=>'<a href="%1$s" %2$s>Тафсилоти версияи %3$s-ро бинед</a> ё <a href="%4$s" %5$s target="_blank">ҳоло навсозӣ кунед</a>.','View %1$s version %2$s details'=>'Дидани тафсилоти версияи %2$s-и %1$s','Update %s now'=>'%s-ро ҳоло навсозӣ кунед','Mobile Agent Rules'=>'Қидаҳои агенти мобилӣ','<p>Please add/replace the following codes into the beginning of %1$s:</p> %2$s'=>'<p>Лутфан рамзҳои зеринро ба ибтидои %1$s илова кунед ё иваз намоед:</p> %2$s','Cleaned up unfinished data successfully.'=>'Маълумоти нотамом бомуваффақият тоза карда шуд.','Reset image optimization counter successfully.'=>'Ҳисобкунаки беҳсозии тасвир бомуваффақият барқарор карда шуд.','Destroy all optimization data successfully.'=>'Маълумоти беҳсозӣ бомуваффақият нобуд карда шуд.','Rescanned successfully.'=>'Аз нав бомуваффақият сканер карда шуд.','Rescanned %d images successfully.'=>'%d тасвир бомуваффақият аз нав скан карда шуд.','Calculated backups successfully.'=>'Нусхаҳои эҳтиётӣ бомуваффақият ҳисоб карда шуданд.','Removed backups successfully.'=>'Нusусҳои эҳтиётӣ бомуваффақият нест карда шуданд.','Switched images successfully.'=>'Тасвирҳо бомуваффақият иваз карда шуданд.','Switched to optimized file successfully.'=>'Гузариш ба файли беҳсозшуда бомуваффақият анҷом ёфт.','Disabled WebP file successfully.'=>'Файли WebP бомуваффақият ғайрифаъол карда шуд.','Enabled WebP file successfully.'=>'Файли WebP бо муваффақият фаъол карда шуд.','Disabled AVIF file successfully.'=>'Файли AVIF бо муваффақият ғайрифаъол карда шуд.','Enabled AVIF file successfully.'=>'Файли AVIF бо муваффақият фаъол карда шуд.','Restored original file successfully.'=>'Файли аслӣ бо муваффақият барқарор карда шуд.','Reset the optimized data successfully.'=>'Маълумоти мувофиқашуда бомуваффақият барқарор карда шуд.','Started async image optimization request'=>'Дархости оптимизатсияи асинхронии тасвир оғоз ёфт','Pull Cron is running'=>'Пулл Крон кор карда истодааст','Some optimized image file(s) has expired and was cleared.'=>'Баъзе файл(ҳо)и тасвири оптимизатсияшуда муҳлати корашон тамом шуда, тоза карда шуданд.','Pulled WebP image md5 does not match the notified WebP image md5.'=>'MD5-и тасвири WebP-и кашидашуда бо MD5-и тасвири WebP-и огоҳшуда мувофиқат намекунад.','Pulled AVIF image md5 does not match the notified AVIF image md5.'=>'MD5-и тасвири AVIF-и гирифташуда ба MD5-и тасвири AVIF-и огоҳонидашуда мувофиқат намекунад.','One or more pulled images does not match with the notified image md5'=>'Яке ё чанде аз тасвирҳои гирифташуда бо md5-и тасвири огоҳшуда мувофиқат намекунад','Pushed %1$s to Cloud server, accepted %2$s.'=>'%1$s ба сервери абрӣ фиристода шуд, %2$s қабул шуд.','Cleared %1$s invalid images.'=>'%1$s тасвири нодуруст тоза карда шуд.','No valid image found in the current request.'=>'Дар дархости ҷорӣ ягон тасвири эътиборнок ёфт нашуд.','No valid image found by Cloud server in the current request.'=>'Дар дархости ҷорӣ аз ҷониби сервери Cloud ягон тасвири эътиборнок ёфт нашуд.','Import failed due to file error.'=>'Воридот аз сабаби хатои файл иҷро нашуд.','Imported setting file %s successfully.'=>'Файли танзимоти воридшуда %s бо муваффақият иҷро шуд.','Reset successfully.'=>'Бомувафқият барқарор карда шуд.','Images not requested'=>'Тасвирҳо дархост нашудаанд','Images ready to request'=>'Тасвирҳо барои дархост омодаанд','Images requested'=>'Тасвирҳои дархостшуда','Images notified to pull'=>'Тасвирҳо барои зеркашӣ хабар дода шуданд','Images optimized and pulled'=>'Суратҳо мутобиқ ва дарёфт карда шуданд','Unable to automatically add %1$s as a Domain Alias for main %2$s domain, due to potential CDN confl